<?php
session_start(); require_once __DIR__.'/functions.php'; require_user();$uid=user_id();$id=(int)($_GET['id']??0);
$s=$conn->prepare("SELECT p.*,py.jumlah,py.status payment_status,py.bukti_bayar,py.catatan payment_catatan,h.nilai,h.status_lulus,s.nomor_sertifikat,s.file_sertifikat FROM pendaftaran p LEFT JOIN pembayaran py ON py.id_pendaftaran=p.id_pendaftaran LEFT JOIN hasil h ON h.id_pendaftaran=p.id_pendaftaran LEFT JOIN sertifikat s ON s.id_pendaftaran=p.id_pendaftaran WHERE p.id_pendaftaran=? AND p.id_user=? LIMIT 1");$s->bind_param('ii',$id,$uid);$s->execute();$app=$s->get_result()->fetch_assoc();if(!$app){header('Location: dashboard.php');exit;}$b=$conn->prepare('SELECT * FROM berkas WHERE id_pendaftaran=? ORDER BY created_at DESC');$b->bind_param('i',$id);$b->execute();$files=$b->get_result();
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Detail Pendaftaran</title><link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@400;600;700;800&display=swap" rel="stylesheet"><style>*{box-sizing:border-box}body{font-family:Montserrat,sans-serif;background:#f4f6f9;margin:0}.wrap{max-width:950px;margin:35px auto;padding:20px}.card{background:#fff;border-radius:15px;padding:25px;box-shadow:0 8px 25px rgba(0,0,0,.06);margin-bottom:20px}h1,h2{color:#1e3a8a}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:15px}.box{background:#f8fafc;padding:15px;border-radius:10px}.badge{padding:6px 10px;border-radius:30px;font-size:.75rem;font-weight:700;background:#fff7ed;color:#c2410c}.btn{display:inline-block;background:#1e3a8a;color:#fff;padding:11px 15px;border-radius:8px;text-decoration:none;font-weight:700;font-size:.85rem}.btn.gold{background:#dea057}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #eee;text-align:left;font-size:.85rem}</style></head><body><div class="wrap"><a class="btn" href="dashboard.php">← Dashboard</a><div class="card"><h1><?=e($app['jenis'])?> #<?=e($app['id_pendaftaran'])?></h1><div class="grid"><div class="box"><b>Tanggal</b><br><?=e(date('d-m-Y',strtotime($app['tanggal'])))?></div><div class="box"><b>Status</b><br><span class="badge"><?=e(app_status_label($app['status']))?></span></div><div class="box"><b>Pembayaran</b><br><?=e(ucwords(str_replace('_',' ',$app['payment_status']??'belum_bayar')))?></div><div class="box"><b>Hasil</b><br><?=e($app['status_lulus']??'Belum Diumumkan')?> <?=isset($app['nilai'])?'('.e($app['nilai']).')':''?></div></div><p><?=e($app['catatan_admin']??'')?></p></div>
<div class="card"><h2>1. Berkas Persyaratan</h2><p>Unggah berkas satu per satu. Format PDF/JPG/PNG, maksimal 5 MB.</p><a class="btn" href="upload_berkas.php?id=<?=$id?>">Upload Berkas</a><table><tr><th>Jenis</th><th>File</th><th>Status</th></tr><?php while($r=$files->fetch_assoc()):?><tr><td><?=e($r['jenis_berkas'])?></td><td><a href="../uploads/sertifikasi/<?=rawurlencode($r['file'])?>" target="_blank">Lihat</a></td><td><?=e(ucfirst($r['status']))?> <?=e($r['keterangan']??'')?></td></tr><?php endwhile;?></table></div>
<div class="card"><h2>2. Pembayaran QRIS</h2><p>Gunakan QRIS kantor yang tersedia di halaman ini, lalu unggah bukti pembayaran.</p><div style="text-align:center;margin:20px"><img src="../uploads/qris/qris.png" alt="QRIS PERADI" style="max-width:300px;width:100%;border:1px solid #ddd;border-radius:12px;padding:10px" onerror="this.style.display='none';document.getElementById('qris-note').style.display='block'"><div id="qris-note" style="display:none;background:#fff7ed;padding:20px;border-radius:10px;color:#9a3412">File QRIS belum dipasang. Simpan QRIS kantor sebagai <b>uploads/qris/qris.png</b>.</div></div><p><b>Total: <?=money($app['jumlah']??0)?></b></p><a class="btn gold" href="pembayaran.php?id=<?=$id?>">Konfirmasi Pembayaran</a></div>
<?php if($app['status_lulus']&&$app['status_lulus']!=='Belum Diumumkan'):?><div class="card"><h2>3. Hasil Ujian</h2><p>Status: <b><?=e($app['status_lulus'])?></b> — Nilai: <b><?=e($app['nilai'])?></b></p><?php if($app['file_sertifikat']):?><a class="btn" href="../uploads/sertifikat/<?=rawurlencode($app['file_sertifikat'])?>" target="_blank" download>Unduh Sertifikat</a><?php endif;?></div><?php endif;?></div></body></html>
